// Import of required libraries
import { test, expect, SkyrampClient, getValue, getResponseValue } from '@skyramp/skyramp';
import { get_users, update_user } from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Ghost " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const endpoint1GetResponse = await get_users(client, headers);

    // Generated Assertions
    expect(endpoint1GetResponse.statusCode, 'status code').toBe(200);

    const existingUsers = JSON.parse((endpoint1GetResponse as any).responseBody).users;
    expect(existingUsers.length, 'limit=1 is honoured').toBe(1);
    expect(existingUsers[0].id, 'user id').toMatch(/^[0-9a-f]{24}$/i);
    expect(existingUsers[0].email, 'user email').toContain("@");
    expect(existingUsers[0].status, 'user status').toBe("active");

    const usersPutResponse = await update_user(
        client,
        headers,
        getResponseValue(endpoint1GetResponse, "users.0.id"),
        "Editor Plus"
    );

    // "Editor Plus" is listed in ASSIGNABLE_ROLES in
    // ghost/core/core/server/api/endpoints/users.js, so assigning it by role name — the
    // form the Admin API documents and ghost/core/test/e2e-api/admin/users.test.js
    // exercises — must be accepted.
    expect(usersPutResponse.statusCode, 'status code').toBe(200);

    const editedUsers = JSON.parse((usersPutResponse as any).responseBody).users;
    const assignedRoles = editedUsers[0].roles;
    expect(Array.isArray(assignedRoles), 'roles is an array').toBe(true);
    expect(assignedRoles.length, 'exactly one role per user').toBe(1);
    expect(assignedRoles[0].name, 'assigned role name').toBe("Editor Plus");
    expect(assignedRoles[0].description, 'assigned role description').toBe("Editors with extended publishing privileges");
    expect(getValue(usersPutResponse, "users.0.id"), 'edited user id').toBe(getResponseValue(endpoint1GetResponse, "users.0.id"));
    expect(editedUsers.length, 'only one user is returned').toBe(1);
});
